"""Lingue della pagina utente e delle notifiche: italiano (principale), inglese, tedesco, francese.

I testi restano scritti in italiano nel codice; le traduzioni stanno in TRANSLATIONS, con chiave il
testo italiano. Un testo con parti variabili ha i segnaposto {0}, {1}…: «{0} dispositivi» →
«{0} devices». La traduzione può cambiare l'ordine dei segnaposto («{1} … {0}»).

- Pagina di stato: il traduttore JavaScript (I18N_JS) sostituisce nel browser ogni testo italiano
  che compare, compresi quelli costruiti dal codice, i messaggi del server e le finestre di conferma.
- Notifiche (email, Telegram, ntfy): tr_text() nella lingua del destinatario, al momento dell'invio.
- Eventi: salvati in italiano, tradotti quando si mostrano (anche quelli già salvati).

Per trovare i testi nuovi ancora senza traduzione: python3 tools/i18n-estrai.py server --mancanti
"""
__version__ = "1.1.20261028-180000"
import json
import re

LANGS = ("it", "en", "de", "fr")
DEFAULT = "it"
NAMES = {"it": "Italiano", "en": "English", "de": "Deutsch", "fr": "Français"}
LOCALES = {"it": "it-IT", "en": "en-GB", "de": "de-DE", "fr": "fr-FR"}
COOKIE = "netmon_lang"

_PH = re.compile(r"\{(\d+)\}")
_TAG = re.compile(r"^\[([A-ZÀ-Ù' ]{2,20})\]\s+(.+)$")


def valid(lang):
    return lang if lang in LANGS else None


def from_accept_language(header):
    """Prima lingua supportata tra quelle del browser (Accept-Language), oppure None."""
    best = []
    for i, part in enumerate((header or "").split(",")):
        bits = part.strip().split(";")
        code = bits[0].strip().lower()[:2]
        q = 1.0
        for b in bits[1:]:
            if b.strip().startswith("q="):
                try:
                    q = float(b.strip()[2:])
                except ValueError:
                    q = 0.0
        if code in LANGS:
            best.append((-q, i, code))
    return sorted(best)[0][2] if best else None


def pick(user_lang=None, cookie=None, accept=None):
    """Lingua da usare: quella dell'account, poi quella scelta in questo browser (cookie), poi quella
    del browser, altrimenti l'italiano."""
    return valid(user_lang) or valid(cookie) or from_accept_language(accept) or DEFAULT


class Translator:
    """Traduce un testo italiano: corrispondenza esatta, poi i modelli con segnaposto (le parti
    variabili si traducono a loro volta, se sono testi noti), poi i pezzi separati da « · »."""

    def __init__(self, table):
        self.exact, self.cache = {}, {}
        self.by_prefix, self.by_suffix, self.loose = {}, {}, []
        for key, value in (table or {}).items():
            if not value:
                continue
            k = " ".join(key.split())
            if _PH.search(k):
                self._add_pattern(k, value)
            else:
                self.exact[k] = value.replace("{{", "{").replace("}}", "}")
        for lst in list(self.by_prefix.values()) + list(self.by_suffix.values()) + [self.loose]:
            lst.sort(key=lambda p: -p[3])                  # prima i modelli con più testo fisso

    def _add_pattern(self, key, value):
        parts = _PH.split(key)                             # testo, numero, testo, numero…
        rx, order, lits = "^", [], []
        for i, part in enumerate(parts):
            if i % 2:
                rx += "(.+?)"
                order.append(int(part))
            else:
                lit = part.replace("{{", "{").replace("}}", "}")
                rx += re.escape(lit)
                lits.append(lit)
        literal = sum(len(x.strip()) for x in lits)
        if literal < 3:
            return
        entry = (re.compile(rx + "$", re.S), order, value, literal)
        first, last = lits[0], lits[-1]
        if len(first) >= 3:
            self.by_prefix.setdefault(first[:3], []).append(entry)
        elif len(last) >= 3:
            self.by_suffix.setdefault(last[-3:], []).append(entry)
        else:
            self.loose.append(entry)

    def tr(self, text, depth=0):
        if not text or not text.strip():
            return text
        m = re.match(r"^(\s*)(.*?)(\s*)$", text, re.S)
        lead, core, trail = m.group(1), " ".join(m.group(2).split()), m.group(3)
        hit = self.cache.get(core)
        if hit is None:
            hit = self._find(core, depth)
            if len(self.cache) > 20000:
                self.cache.clear()
            self.cache[core] = hit
        return lead + hit + trail if hit != core else text

    def _find(self, core, depth):
        if core in self.exact:
            return self.exact[core]
        cands = self.by_prefix.get(core[:3], []) + self.by_suffix.get(core[-3:], []) + self.loose
        for rx, order, value, _ in cands:
            m = rx.match(core)
            if not m:
                continue
            groups = {}
            for n, g in zip(order, m.groups()):
                groups[n] = self.tr(g, depth + 1) if depth < 3 else g
            return _PH.sub(lambda x: groups.get(int(x.group(1)), x.group(0)), value) \
                .replace("{{", "{").replace("}}", "}")
        m = _TAG.match(core)
        if m and depth < 3:                            # «[CRITICO] testo»: etichetta e testo a parte
            return self.tr("[" + m.group(1) + "]", depth + 1) + " " + self.tr(m.group(2), depth + 1)
        for sep in (" · ", ", "):                     # elenchi: pezzo per pezzo
            if sep in core and depth < 3:
                segs = core.split(sep)
                out = [self.tr(s, depth + 1) for s in segs]
                if out != segs:
                    return sep.join(out)
        return core

    def text(self, text):
        """Testo su più righe (corpo di email e notifiche): riga per riga, e se una riga non è nota
        frase per frase."""
        out = []
        for line in (text or "").split("\n"):
            t = self.tr(line)
            if t == line and line.strip() and re.search(r"[.!?:]\s", line):
                pieces = re.split(r"(?<=[.!?:])(\s+)", line)
                t = "".join(p if i % 2 else self.tr(p) for i, p in enumerate(pieces))
            out.append(t)
        return "\n".join(out)


_translators = {}


def table(lang, admin=True):
    """Dizionario di una lingua: quello della pagina utente, più (admin) quello del pannello e degli
    avvisi agli amministratori. In caso di doppione vale quello della pagina utente."""
    lang = valid(lang) or DEFAULT
    if lang == DEFAULT:
        return {}
    base = TRANSLATIONS.get(lang, {})
    if not admin:
        return base
    from i18n_admin import ADMIN_TRANSLATIONS
    return {**{k: v for k, v in ADMIN_TRANSLATIONS.get(lang, {}).items() if v}, **base}


def translator(lang):
    lang = valid(lang) or DEFAULT
    if lang not in _translators:
        _translators[lang] = Translator(table(lang))
    return _translators[lang]


_DECIMAL = re.compile(r"(\d),(\d)")
POINT_DECIMAL = {"en"}          # lingue col punto decimale: «38,5 °C» diventa «38.5 °C»


def numbers(lang, text):
    return _DECIMAL.sub(r"\1.\2", text) if lang in POINT_DECIMAL and text else text


def tr(lang, text):
    return text if (valid(lang) or DEFAULT) == DEFAULT else numbers(lang, translator(lang).tr(text))


def tr_text(lang, text):
    return text if (valid(lang) or DEFAULT) == DEFAULT else numbers(lang, translator(lang).text(text))


def page_script(lang, admin=False):
    """<script> con lingua, dizionario e traduttore, da mettere in cima alla pagina (admin: quella
    del pannello di amministrazione, con anche il suo dizionario)."""
    lang = valid(lang) or DEFAULT
    data = json.dumps({"lang": lang, "locale": LOCALES[lang], "names": NAMES, "table": table(lang, admin)},
                      ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    return "<script>window.I18N=" + data + ";\n" + I18N_JS + "</script>"


# Traduttore della pagina (stesso algoritmo di Translator). Lavora sul DOM: traduce i testi e gli
# attributi title/placeholder/aria-label già presenti e quelli che il codice aggiunge dopo
# (MutationObserver), e i messaggi di confirm/alert/prompt. Non tocca ciò che sta dentro un
# elemento con translate="no" (nomi scelti dagli utenti). Copia identica in probe/config_web.py.
I18N_JS = r"""
(function () {
  const I = window.I18N || {}; const table = I.table || {};
  I.t = s => s; I.text = s => s;
  if (I.lang === "it" || !Object.keys(table).length) { window.I18N = I; return; }
  const PH = /\{(\d+)\}/g, exact = new Map(), byPre = new Map(), bySuf = new Map(), loose = [], cache = new Map();
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const unb = s => s.replace(/\{\{/g, "{").replace(/\}\}/g, "}");
  const norm = s => s.replace(/\s+/g, " ").trim();
  const units = new Map();                // testi con formattazione (<strong>…), tradotti interi
  const canon = document.createElement("div");
  for (const [k0, v] of Object.entries(table)) {
    if (!v) continue;
    const k = norm(k0);
    if (k.includes("<")) { canon.innerHTML = k; units.set(norm(canon.innerHTML), v); continue; }
    if (!/\{\d+\}/.test(k)) { exact.set(unb(k), unb(v)); continue; }
    const parts = k.split(/(\{\d+\})/), order = [], lits = [];
    let rx = "^";
    parts.forEach((p, i) => {
      const m = /^\{(\d+)\}$/.exec(p);
      if (m) { rx += "(.+?)"; order.push(+m[1]); } else { const l = unb(p); rx += esc(l); lits.push(l); }
    });
    const lit = lits.reduce((a, l) => a + l.trim().length, 0);
    if (lit < 3) continue;
    const e = { rx: new RegExp(rx + "$", "s"), order, v, lit };
    const first = lits[0] || "", last = lits[lits.length - 1] || "";
    if (first.length >= 3) { const key = first.slice(0, 3); if (!byPre.has(key)) byPre.set(key, []); byPre.get(key).push(e); }
    else if (last.length >= 3) { const key = last.slice(-3); if (!bySuf.has(key)) bySuf.set(key, []); bySuf.get(key).push(e); }
    else loose.push(e);
  }
  [...byPre.values(), ...bySuf.values(), loose].forEach(l => l.sort((a, b) => b.lit - a.lit));
  function find(core, depth) {
    const x = exact.get(core);
    if (x !== undefined) return x;
    const cands = (byPre.get(core.slice(0, 3)) || []).concat(bySuf.get(core.slice(-3)) || [], loose);
    for (const e of cands) {
      const m = e.rx.exec(core);
      if (!m) continue;
      const g = {};
      e.order.forEach((n, i) => { g[n] = depth < 3 ? tr(m[i + 1], depth + 1) : m[i + 1]; });
      return unb(e.v.replace(PH, (all, n) => (n in g ? g[n] : all)));
    }
    const tg = /^\[([A-ZÀ-Ù' ]{2,20})\]\s+([\s\S]+)$/.exec(core);
    if (tg && depth < 3) return tr("[" + tg[1] + "]", depth + 1) + " " + tr(tg[2], depth + 1);
    for (const sep of [" · ", ", "]) {                 // elenchi: pezzo per pezzo
      if (depth < 3 && core.includes(sep)) {
        const segs = core.split(sep), out = segs.map(s => tr(s, depth + 1));
        if (out.some((s, i) => s !== segs[i])) return out.join(sep);
      }
    }
    return core;
  }
  function tr(text, depth = 0) {
    if (!text || !/[A-Za-zÀ-ÿ]/.test(text)) return text;
    const m = /^(\s*)([\s\S]*?)(\s*)$/.exec(text), core = norm(m[2]);
    let hit = cache.get(core);
    if (hit === undefined) { hit = find(core, depth); if (cache.size > 20000) cache.clear(); cache.set(core, hit); }
    return hit === core ? text : m[1] + hit + m[3];
  }
  function trText(text) {
    return String(text).split("\n").map(line => {
      let t = tr(line);
      if (t === line && /[.!?:]\s/.test(line)) t = line.split(/(?<=[.!?:])(\s+)/).map((p, i) => i % 2 ? p : tr(p)).join("");
      return t;
    }).join("\n");
  }
  I.t = tr; I.text = trText;
  const done = new WeakMap(), ATTRS = ["title", "placeholder", "aria-label", "alt"];
  const INLINE = new Set(["STRONG", "EM", "B", "I", "CODE", "BR", "A", "KBD"]);
  const skip = n => { const e = n.nodeType === 1 ? n : n.parentElement; return !e || !!e.closest('[translate="no"],script,style'); };
  const num = I.lang === "en" ? s => s.replace(/(\d),(\d)/g, "$1.$2") : s => s;   // punto decimale
  function doText(n) {
    if (done.get(n) === n.data || skip(n)) return;
    const t = num(tr(n.data));
    if (t !== n.data) n.data = t;
    done.set(n, n.data);
  }
  function doAttrs(e) {
    for (const a of ATTRS) {
      const v = e.getAttribute(a);
      if (!v) continue;
      const k = "a:" + a, seen = done.get(e) || {};
      if (seen[k] === v) continue;
      let t = tr(v);
      // suggerimento fatto di più frasi senza una traduzione intera: frase per frase
      if (t === v && /[.!?]\s/.test(v)) t = v.split(/(?<=[.!?])(\s+)/).map((p, i) => i % 2 ? p : tr(p)).join("");
      t = num(t);
      if (t !== v) e.setAttribute(a, t);
      seen[k] = t; done.set(e, seen);
    }
    if (e.tagName === "INPUT" && /^(button|submit)$/.test(e.type) && e.value) { const t = tr(e.value); if (t !== e.value) e.value = t; }
  }
  function doUnit(e) {                    // elemento con solo formattazione dentro: tradotto intero
    if (!units.size || !e.firstElementChild || e.querySelector("[id]")) return false;
    for (const c of e.children) if (!INLINE.has(c.tagName)) return false;
    const v = units.get(norm(e.innerHTML));
    if (v === undefined) return false;
    e.innerHTML = v; return true;
  }
  function walk(root) {
    if (root.nodeType === 3) { doText(root); return; }
    if (root.nodeType !== 1 || skip(root)) return;
    const stack = [root];
    while (stack.length) {
      const e = stack.pop();
      if (e.nodeType !== 1 || e.getAttribute("translate") === "no" || e.tagName === "SCRIPT" || e.tagName === "STYLE") continue;
      doAttrs(e);
      if (doUnit(e)) continue;
      for (const c of e.childNodes) { if (c.nodeType === 3) doText(c); else if (c.nodeType === 1) stack.push(c); }
    }
  }
  const obs = new MutationObserver(list => {
    for (const m of list) {
      if (m.type === "characterData") doText(m.target);
      else if (m.type === "attributes") { if (!skip(m.target)) doAttrs(m.target); }
      else m.addedNodes.forEach(walk);
    }
  });
  function start() {
    walk(document.documentElement);
    obs.observe(document.documentElement, { subtree: true, childList: true, characterData: true,
                                            attributes: true, attributeFilter: ATTRS });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start); else start();
  const oc = window.confirm.bind(window), oa = window.alert.bind(window), op = window.prompt.bind(window);
  window.confirm = m => oc(trText(m)); window.alert = m => oa(trText(m)); window.prompt = (m, d) => op(trText(m), d);
  window.I18N = I;
})();
"""


