        "When the server moves to a new version of netmon, your probes update themselves within a few hours: during the update a probe skips a couple of checks. If you turn this off they stay at the current version until you update them yourself (<i>Probe status</i> → <i>Update netmon</i>); updates of all probes made by the administrator skip them too. The probe on Home Assistant updates from Home Assistant instead.",
        "Wenn der Server auf eine neue Version von netmon wechselt, aktualisieren sich deine Sonden innerhalb weniger Stunden selbst: während des Updates lässt eine Sonde ein paar Prüfungen aus. Schaltest du das aus, bleiben sie auf der aktuellen Version, bis du sie selbst aktualisierst (<i>Sondenstatus</i> → <i>netmon aktualisieren</i>); auch Updates aller Sonden durch den Administrator lassen sie aus. Die Sonde auf Home Assistant wird stattdessen über Home Assistant aktualisiert.",
